{
  "conversations": [
    {
      "title": "State my dietary restrictions",
      "lines": [
        { "speaker": "you", "text": "I'm vegan." },
        { "speaker": "partner", "text": "Vegan?" },
        { "speaker": "you", "text": "No meat, fish, eggs, or dairy." },
        { "speaker": "partner", "text": "What about dashi broth?" },
        { "speaker": "you", "text": "No fish broth, please." }
      ]
    },
    {
      "title": "Ask about hidden ingredients",
      "lines": [
        { "speaker": "you", "text": "Does this have egg in it?" },
        { "speaker": "partner", "text": "Yes, it does." },
        { "speaker": "you", "text": "Does this have dairy in it?", "or": true },
        { "speaker": "partner", "text": "No, it doesn't.", "or": true },
        { "speaker": "you", "text": "Does this have honey in it?", "or": true },
        { "speaker": "partner", "text": "Let me check the kitchen." }
      ]
    },
    {
      "title": "Order vegan dishes",
      "lines": [
        { "speaker": "you", "text": "I'll take the vegetable salad." },
        { "speaker": "partner", "text": "Anything else?" },
        { "speaker": "you", "text": "I'll have the tofu dish, please." },
        { "speaker": "you", "text": "I'll take the edamame, please.", "or": true },
        { "speaker": "partner", "text": "Coming right up." }
      ]
    }
  ]
}
